urlset:
{%- for sitemap_entry in entries %}

    {{ sitemap_entry.permalink | trim_end_matches(pat='/') | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated | date(format="%+") }}
    {%- elif sitemap_entry.date %}
    {{ sitemap_entry.date | date(format="%+") }}
    {%- endif %}

{%- endfor %}
